def count_blocks_and_trailing(nums):
    """Find number of contiguous blocks and trailing zeros"""
    if len(nums) == 0:
        return 0, 0

    blocks = 0
    trailing_zeros = 0
    in_block = False

    for x in nums:
        if x != 0:
            if not in_block:
                blocks += 1
                in_block = True
        else:
            if in_block:
                in_block = False
            trailing_zeros += 1

    return blocks, trailing_zeros

