def parse_blocks(nums):
    """Parse into list of (start_col, end_col) for each block"""
    blocks = []
    if len(nums) == 0:
        return blocks
    start = None
    for i, x in enumerate(nums):
        if x != 0 and start is None:
            start = i
        elif x == 0 and start is not None:
            blocks.append((start, i-1))
            start = None
    if start is not None:
        blocks.append((start, len(nums)-1))
    return blocks

print("\nBlocks in left section:")
